    progress({ id, label, state: "running" });
    note(`${label}…`);
    try {
      const result = await work();
      progress({ id, label, state: "done" });
      return result;
    } catch (error) {
      progress({ id, label, state: "error", detail: (error as Error).message });
      note(`${label} failed: ${(error as Error).stack ?? error}`);
      throw error;
    }
